def oauth_status(user_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0441000" if __import__("os").path.isdir("./environment_mix/0441000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(status_code, jira_connection_id=None, oauth_session_id=None, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"rql_{int(time.time()*1000)}",
            "endpoint": "oauth_status",
            "user_id": user_id,
            "jira_connection_id": jira_connection_id,
            "oauth_session_id": oauth_session_id,
            "status": status_code,
            "detail": detail,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now()
        })
        _save("request_logs.json", logs)

    try:
        if not isinstance(user_id, str) or not re.match(r"^usr_[0-9A-HJKMNP-TV-Z]{16,}$", user_id):
            _log("VALIDATION_ERROR", detail="invalid user_id")
            return _err("VALIDATION_ERROR", "user_id is missing or invalid.", field="user_id")

        users = _load("users.json")
        if not isinstance(users, list):
            users = []
        user = next((u for u in users if u.get("id") == user_id), None)
        if not user:
            _log("NOT_FOUND", detail="user not found")
            return _err("NOT_FOUND", "User not found.", user_id=user_id)

        connections = _load("jira_connections.json")
        if not isinstance(connections, list):
            connections = []
        conn = next((c for c in connections if c.get("user_id") == user_id), None)
        if not conn:
            _log("NOT_FOUND", detail="no connection for user")
            return _err("NOT_FOUND", "No stored Jira connection for this user.", user_id=user_id)

        # If token_expires_at < now() then set status to 'expired' (if transition is legal).
        now_dt = datetime.datetime.utcnow()
        token_expires_at = _parse_dt(conn.get("token_expires_at"))
        updated = False
        if token_expires_at and token_expires_at < now_dt and conn.get("status") in ("active", "error"):
            # allowed transitions: active->expired, error->(no direct) but error has no 'expired' transition in schema;
            # only update when legal.
            if conn.get("status") == "active":
                conn["status"] = "expired"
                conn["updated_at"] = _now()
                updated = True

        # Most recent oauth_sessions row with status in ('created','browser_opened','callback_received')
        sessions = _load("oauth_sessions.json")
        if not isinstance(sessions, list):
            sessions = []
        candidate_statuses = {"created", "browser_opened", "callback_received"}
        relevant = [s for s in sessions if s.get("user_id") == user_id and s.get("jira_connection_id") == conn.get("id") and s.get("status") in candidate_statuses]
        def _key(s):
            dt = _parse_dt(s.get("updated_at")) or _parse_dt(s.get("created_at")) or datetime.datetime.min
            return dt
        relevant.sort(key=_key, reverse=True)
        latest_session = relevant[0] if relevant else None

        if updated:
            # persist connection update if any
            for i, c in enumerate(connections):
                if c.get("id") == conn.get("id"):
                    connections[i] = conn
                    break
            _save("jira_connections.json", connections)

        # Never return token material fields
        conn_out = {k: v for k, v in conn.items() if k not in ("access_token_ciphertext", "refresh_token_ciphertext")}
        sess_out = None
        if latest_session:
            sess_out = {k: v for k, v in latest_session.items() if k != "pkce_code_verifier_ciphertext"}

        body = {
            "user": {"id": user_id, "status": user.get("status"), "display_name": user.get("display_name"), "email": user.get("email")},
            "jira_connection": conn_out,
            "oauth_session": sess_out
        }
        _log("OK", jira_connection_id=conn.get("id"), oauth_session_id=(latest_session or {}).get("id"))
        return body
    except Exception as e:
        _log("ERROR", detail=str(e))
        return _err("CONFLICT", "Unexpected server error.", detail=str(e))

def test_jira_connection(jira_connection_id=None, user_id=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0441000" if __import__("os").path.isdir("./environment_mix/0441000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(status_code, resolved_jcn=None, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"rql_{int(time.time()*1000)}",
            "endpoint": "test_jira_connection",
            "user_id": user_id,
            "jira_connection_id": resolved_jcn or jira_connection_id,
            "status": status_code,
            "detail": detail,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now()
        })
        _save("request_logs.json", logs)

    try:
        if jira_connection_id is None and user_id is None:
            _log("VALIDATION_ERROR", detail="neither jira_connection_id nor user_id provided")
            return _err("VALIDATION_ERROR", "Either jira_connection_id or user_id must be provided.")

        if jira_connection_id is not None:
            if not isinstance(jira_connection_id, str) or not re.match(r"^jcn_[0-9A-HJKMNP-TV-Z]{16,}$", jira_connection_id):
                _log("VALIDATION_ERROR", detail="invalid jira_connection_id")
                return _err("VALIDATION_ERROR", "jira_connection_id is invalid.", field="jira_connection_id")

        if user_id is not None:
            if not isinstance(user_id, str) or not re.match(r"^usr_[0-9A-HJKMNP-TV-Z]{16,}$", user_id):
                _log("VALIDATION_ERROR", detail="invalid user_id")
                return _err("VALIDATION_ERROR", "user_id is invalid.", field="user_id")

        users = _load("users.json")
        if not isinstance(users, list):
            users = []
        connections = _load("jira_connections.json")
        if not isinstance(connections, list):
            connections = []

        conn = None
        if jira_connection_id:
            conn = next((c for c in connections if c.get("id") == jira_connection_id), None)
            if not conn:
                _log("NOT_FOUND", detail="connection not found")
                return _err("NOT_FOUND", "Jira connection not found.", jira_connection_id=jira_connection_id)
            user_id = conn.get("user_id")
        else:
            # resolve user's connection
            user = next((u for u in users if u.get("id") == user_id), None)
            if not user:
                _log("NOT_FOUND", detail="user not found")
                return _err("NOT_FOUND", "User not found.", user_id=user_id)
            conn = next((c for c in connections if c.get("user_id") == user_id), None)
            if not conn:
                _log("NOT_FOUND", detail="no connection for user")
                return _err("NOT_FOUND", "No Jira connection found for this user.", user_id=user_id)

        user = next((u for u in users if u.get("id") == user_id), None)
        if not user:
            _log("NOT_FOUND", resolved_jcn=conn.get("id"), detail="user missing for connection")
            return _err("NOT_FOUND", "User not found for the referenced connection.", user_id=user_id)

        if user.get("status") in ("disabled", "deleted"):
            _log("UNAUTHORIZED", resolved_jcn=conn.get("id"), detail="user disabled/deleted")
            return _err("UNAUTHORIZED", "User is not permitted to test Jira connection in the current state.", user_status=user.get("status"))

        if conn.get("status") not in ("active", "expired"):
            _log("UNAUTHORIZED", resolved_jcn=conn.get("id"), detail=f"connection status {conn.get('status')} not testable")
            return _err("UNAUTHORIZED", "Connection is not in a testable state.", jira_connection_status=conn.get("status"))

        # Simulate real behavior based on stored token fields and expiry.
        now_dt = datetime.datetime.utcnow()
        token_exp = _parse_dt(conn.get("token_expires_at"))
        has_access = bool(conn.get("access_token_ciphertext"))
        has_refresh = bool(conn.get("refresh_token_ciphertext"))

        result = {"reachable": False, "authenticated": False, "refreshed": False}

        if has_access and (token_exp is None or token_exp > now_dt):
            # success
            conn["last_tested_at"] = _now()
            conn["last_error"] = None
            if conn.get("status") != "active":
                # expired -> active is legal
                if conn.get("status") == "expired":
                    conn["status"] = "active"
            conn["updated_at"] = _now()
            result.update({"reachable": True, "authenticated": True})
            status = "OK"
        else:
            # attempt refresh if possible
            if has_refresh:
                # treat as successful refresh
                conn["access_token_ciphertext"] = conn.get("access_token_ciphertext") or "enc:refreshed_access_token"
                conn["token_expires_at"] = (now_dt + datetime.timedelta(hours=1)).replace(microsecond=0).isoformat() + "Z"
                conn["last_tested_at"] = _now()
                conn["last_error"] = None
                conn["status"] = "active"
                conn["updated_at"] = _now()
                result.update({"reachable": True, "authenticated": True, "refreshed": True})
                status = "OK"
            else:
                # failure: no valid token; decide expired vs revoked
                # If token_expires_at exists and is in the past -> expired, else revoked (no token/invalid_grant).
                if token_exp and token_exp <= now_dt:
                    # active -> expired is legal
                    if conn.get("status") == "active":
                        conn["status"] = "expired"
                    conn["last_error"] = "access_token_expired"
                else:
                    # active/expired -> revoked is legal
                    if conn.get("status") in ("active", "expired", "error"):
                        conn["status"] = "revoked"
                    conn["last_error"] = "invalid_grant"
                conn["updated_at"] = _now()
                result.update({"reachable": False, "authenticated": False})
                status = "UNAUTHORIZED"

        # persist update
        for i, c in enumerate(connections):
            if c.get("id") == conn.get("id"):
                connections[i] = conn
                break
        _save("jira_connections.json", connections)

        conn_out = {k: v for k, v in conn.items() if k not in ("access_token_ciphertext", "refresh_token_ciphertext")}

        _log(status, resolved_jcn=conn.get("id"), detail=result.get("refreshed") and "refreshed" or None)
        return {"jira_connection": conn_out, "result": result}
    except Exception as e:
        _log("ERROR", resolved_jcn=jira_connection_id, detail=str(e))
        return _err("CONFLICT", "Unexpected server error.", detail=str(e))

def jira_get_issue(jira_connection_id, issue_key, refresh=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0441000" if __import__("os").path.isdir("./environment_mix/0441000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _b32_id(prefix):
        import secrets
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        raw = secrets.token_bytes(12)
        n = int.from_bytes(raw, "big")
        s = ""
        while n > 0:
            n, r = divmod(n, len(alphabet))
            s = alphabet[r] + s
        s = s.rjust(16, "0")
        return f"{prefix}_{s}"

    def _log(status_code, user_id=None, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"rql_{int(time.time()*1000)}",
            "endpoint": "jira_get_issue",
            "user_id": user_id,
            "jira_connection_id": jira_connection_id,
            "status": status_code,
            "detail": detail,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now()
        })
        _save("request_logs.json", logs)

    try:
        if refresh is None:
            refresh = False
        if not isinstance(jira_connection_id, str) or not re.match(r"^jcn_[0-9A-HJKMNP-TV-Z]{16,}$", jira_connection_id):
            _log("VALIDATION_ERROR", detail="invalid jira_connection_id")
            return _err("VALIDATION_ERROR", "jira_connection_id is missing or invalid.", field="jira_connection_id")
        if not isinstance(issue_key, str) or not issue_key.strip() or len(issue_key.strip()) > 50:
            _log("VALIDATION_ERROR", detail="invalid issue_key")
            return _err("VALIDATION_ERROR", "issue_key is missing or invalid.", field="issue_key")
        if not isinstance(refresh, bool):
            _log("VALIDATION_ERROR", detail="refresh not boolean")
            return _err("VALIDATION_ERROR", "refresh must be a boolean.", field="refresh")

        connections = _load("jira_connections.json")
        if not isinstance(connections, list):
            connections = []
        conn = next((c for c in connections if c.get("id") == jira_connection_id), None)
        if not conn:
            _log("NOT_FOUND", detail="connection not found")
            return _err("NOT_FOUND", "Jira connection not found.", jira_connection_id=jira_connection_id)

        users = _load("users.json")
        if not isinstance(users, list):
            users = []
        user = next((u for u in users if u.get("id") == conn.get("user_id")), None)
        if not user:
            _log("NOT_FOUND", user_id=conn.get("user_id"), detail="user missing for connection")
            return _err("NOT_FOUND", "User not found for the referenced connection.", user_id=conn.get("user_id"))
        if user.get("status") in ("disabled", "deleted"):
            _log("UNAUTHORIZED", user_id=user.get("id"), detail="user disabled/deleted")
            return _err("UNAUTHORIZED", "User is not permitted to fetch issues in the current state.", user_status=user.get("status"))

        # Require active connection (or refresh to become active)
        now_dt = datetime.datetime.utcnow()
        token_exp = _parse_dt(conn.get("token_expires_at"))
        has_access = bool(conn.get("access_token_ciphertext"))
        has_refresh = bool(conn.get("refresh_token_ciphertext"))

        if conn.get("status") != "active":
            # try refresh if expired and refresh token present
            if conn.get("status") == "expired" and has_refresh:
                conn["access_token_ciphertext"] = conn.get("access_token_ciphertext") or "enc:refreshed_access_token"
                conn["token_expires_at"] = (now_dt + datetime.timedelta(hours=1)).replace(microsecond=0).isoformat() + "Z"
                conn["status"] = "active"
                conn["last_error"] = None
                conn["updated_at"] = _now()
                for i, c in enumerate(connections):
                    if c.get("id") == conn.get("id"):
                        connections[i] = conn
                        break
                _save("jira_connections.json", connections)
            else:
                _log("UNAUTHORIZED", user_id=user.get("id"), detail=f"connection not active: {conn.get('status')}")
                return _err("UNAUTHORIZED", "Jira connection is not active.", jira_connection_status=conn.get("status"))

        # If token expired despite status active, attempt refresh else mark expired and deny.
        if conn.get("status") == "active" and has_access and token_exp and token_exp <= now_dt:
            if has_refresh:
                conn["access_token_ciphertext"] = "enc:refreshed_access_token"
                conn["token_expires_at"] = (now_dt + datetime.timedelta(hours=1)).replace(microsecond=0).isoformat() + "Z"
                conn["updated_at"] = _now()
                for i, c in enumerate(connections):
                    if c.get("id") == conn.get("id"):
                        connections[i] = conn
                        break
                _save("jira_connections.json", connections)
            else:
                conn["status"] = "expired"
                conn["last_error"] = "access_token_expired"
                conn["updated_at"] = _now()
                for i, c in enumerate(connections):
                    if c.get("id") == conn.get("id"):
                        connections[i] = conn
                        break
                _save("jira_connections.json", connections)
                _log("UNAUTHORIZED", user_id=user.get("id"), detail="token expired and no refresh")
                return _err("UNAUTHORIZED", "Jira connection token expired.", jira_connection_status="expired")

        issues = _load("jira_issues.json")
        if not isinstance(issues, list):
            issues = []

        issue_key_norm = issue_key.strip()

        cached = next((it for it in issues if it.get("jira_connection_id") == jira_connection_id and it.get("issue_key") == issue_key_norm), None)
        if cached and not refresh:
            # Return cached, but never return forbidden/deleted as success: treat as NOT_FOUND per tool text.
            if cached.get("status") in ("deleted", "forbidden"):
                _log("NOT_FOUND", user_id=user.get("id"), detail=f"cached status {cached.get('status')}")
                return _err("NOT_FOUND", "Issue not found or not accessible.", issue_key=issue_key_norm)
            out = dict(cached)
            _log("OK", user_id=user.get("id"), detail="served_from_cache")
            return {"issue": out, "served_from_cache": True}

        # Offline mode: "fetch from Jira" is represented by interpreting cached raw_issue_json presence.
        # If not cached => treat as 404. If cached has raw_issue_json => update last_fetched_at and return.
        if not cached:
            # Upsert a deleted marker row (as per rule on 404)
            row = {
                "id": _b32_id("jis"),
                "jira_connection_id": jira_connection_id,
                "jira_issue_id": issue_key_norm,  # best-effort stand-in
                "issue_key": issue_key_norm,
                "project_key": issue_key_norm.split("-", 1)[0] if "-" in issue_key_norm else None,
                "issue_type": None,
                "summary": None,
                "status_name": None,
                "assignee_account_id": None,
                "reporter_account_id": None,
                "priority": None,
                "labels": [],
                "sprint_name": None,
                "story_points": None,
                "raw_issue_json": {},
                "last_fetched_at": _now(),
                "status": "deleted",
                "created_at": _now(),
                "updated_at": _now()
            }
            issues.append(row)
            _save("jira_issues.json", issues)
            _log("NOT_FOUND", user_id=user.get("id"), detail="issue not present in cache; marked deleted")
            return _err("NOT_FOUND", "Issue not found.", issue_key=issue_key_norm)

        # cached exists and refresh==True: update last_fetched_at and updated_at; if raw_issue_json empty -> treat 404
        if isinstance(cached.get("raw_issue_json"), dict) and cached.get("raw_issue_json"):
            cached["last_fetched_at"] = _now()
            cached["updated_at"] = _now()
            cached["status"] = "active" if cached.get("status") in ("stale", "forbidden") else cached.get("status", "active")
            # persist
            for i, it in enumerate(issues):
                if it.get("id") == cached.get("id"):
                    issues[i] = cached
                    break
            _save("jira_issues.json", issues)
            _log("OK", user_id=user.get("id"), detail="refreshed_from_cache_payload")
            return {"issue": dict(cached), "served_from_cache": False}

        # raw_issue_json empty => treat as 404 and mark deleted
        # Transition: active/stale/forbidden -> deleted is legal; deleted -> no.
        if cached.get("status") != "deleted":
            cached["status"] = "deleted"
            cached["last_fetched_at"] = _now()
            cached["updated_at"] = _now()
            for i, it in enumerate(issues):
                if it.get("id") == cached.get("id"):
                    issues[i] = cached
                    break
            _save("jira_issues.json", issues)

        _log("NOT_FOUND", user_id=user.get("id"), detail="refresh found no payload; marked deleted")
        return _err("NOT_FOUND", "Issue not found.", issue_key=issue_key_norm)
    except Exception as e:
        _log("ERROR", detail=str(e))
        return _err("CONFLICT", "Unexpected server error.", detail=str(e))

def jira_search(jira_connection_id, user_id, jql, start_at=None, max_results=None, refresh=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0441000" if __import__("os").path.isdir("./environment_mix/0441000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        return dt

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        raw = (str(time.time_ns()) + os.urandom(16).hex()).encode("utf-8")
        digest = hashlib.sha256(raw).digest()
        out = []
        for b in digest:
            out.append(alphabet[b & 31])
            if len(out) >= 22:
                break
        return f"{prefix}_{''.join(out)}"

    def _log_call(endpoint, status, jira_connection_id_used=None, user_id_used=None, extra=None, started=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now()
        latency_ms = None
        if isinstance(started, datetime.datetime):
            latency_ms = int(max(0, (now - started).total_seconds() * 1000))
        row = {
            "id": _gen_id("rql"),
            "endpoint": endpoint,
            "status": status,
            "jira_connection_id": jira_connection_id_used,
            "user_id": user_id_used,
            "timestamp": _iso(now),
            "latency_ms": latency_ms,
        }
        if isinstance(extra, dict) and extra:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_check(endpoint, jira_connection_id_used=None, user_id_used=None):
        # Best-effort: only enforce if rate_limits.json exists with expected shape.
        rate_limits = _load("rate_limits.json")
        if not isinstance(rate_limits, dict):
            return None
        policy = rate_limits.get("policy") if isinstance(rate_limits.get("policy"), dict) else {}
        rules = policy.get(endpoint) if isinstance(policy.get(endpoint), dict) else policy.get("default", {})
        if not isinstance(rules, dict):
            rules = {}
        per_min = rules.get("per_minute")
        per_day = rules.get("per_day")
        scope = rules.get("scope", "user")  # user|connection|global

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None

        now = _now()
        def _match(r):
            if not isinstance(r, dict):
                return False
            if r.get("endpoint") != endpoint:
                return False
            if scope == "user" and user_id_used:
                return r.get("user_id") == user_id_used
            if scope == "connection" and jira_connection_id_used:
                return r.get("jira_connection_id") == jira_connection_id_used
            return True

        def _count_since(delta):
            cutoff = now - delta
            c = 0
            for r in logs:
                if not _match(r):
                    continue
                ts = _parse_dt(r.get("timestamp"))
                if ts and ts >= cutoff:
                    c += 1
            return c

        if isinstance(per_min, int) and per_min >= 0:
            if _count_since(datetime.timedelta(minutes=1)) >= per_min:
                return _err("RATE_LIMIT", "Rate limit exceeded")
        if isinstance(per_day, int) and per_day >= 0:
            if _count_since(datetime.timedelta(days=1)) >= per_day:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    started = _now()

    # Validate inputs
    pat_jcn = re.compile(r"^jcn_[0-9A-HJKMNP-TV-Z]{16,}$")
    pat_usr = re.compile(r"^usr_[0-9A-HJKMNP-TV-Z]{16,}$")
    if not isinstance(jira_connection_id, str) or not pat_jcn.match(jira_connection_id):
        err = _err("VALIDATION_ERROR", "Invalid jira_connection_id")
        _log_call("jira_search", "error", jira_connection_id_used=jira_connection_id, user_id_used=user_id, extra=err, started=started)
        return err
    if not isinstance(user_id, str) or not pat_usr.match(user_id):
        err = _err("VALIDATION_ERROR", "Invalid user_id")
        _log_call("jira_search", "error", jira_connection_id_used=jira_connection_id, user_id_used=user_id, extra=err, started=started)
        return err
    if not isinstance(jql, str) or not jql.strip():
        err = _err("VALIDATION_ERROR", "Invalid jql")
        _log_call("jira_search", "error", jira_connection_id_used=jira_connection_id, user_id_used=user_id, extra=err, started=started)
        return err
    if start_at is None:
        start_at = 0
    if max_results is None:
        max_results = 50
    if refresh is None:
        refresh = False
    if not isinstance(start_at, int) or start_at < 0:
        err = _err("VALIDATION_ERROR", "start_at must be an integer >= 0")
        _log_call("jira_search", "error", jira_connection_id_used=jira_connection_id, user_id_used=user_id, extra=err, started=started)
        return err
    if not isinstance(max_results, int) or max_results < 1 or max_results > 100:
        err = _err("VALIDATION_ERROR", "max_results must be an integer between 1 and 100")
        _log_call("jira_search", "error", jira_connection_id_used=jira_connection_id, user_id_used=user_id, extra=err, started=started)
        return err
    if not isinstance(refresh, bool):
        err = _err("VALIDATION_ERROR", "refresh must be a boolean")
        _log_call("jira_search", "error", jira_connection_id_used=jira_connection_id, user_id_used=user_id, extra=err, started=started)
        return err

    rl = _rate_check("jira_search", jira_connection_id_used=jira_connection_id, user_id_used=user_id)
    if rl:
        _log_call("jira_search", "error", jira_connection_id_used=jira_connection_id, user_id_used=user_id, extra=rl, started=started)
        return rl

    users = _load("users.json")
    conns = _load("jira_connections.json")
    searches = _load("jira_searches.json")
    issues = _load("jira_issues.json")

    if not isinstance(users, list) or not isinstance(conns, list) or not isinstance(searches, list) or not isinstance(issues, list):
        err = _err("CONFLICT", "Datastore is in an unexpected format")
        _log_call("jira_search", "error", jira_connection_id_used=jira_connection_id, user_id_used=user_id, extra=err, started=started)
        return err

    user = next((u for u in users if isinstance(u, dict) and u.get("id") == user_id), None)
    if not user:
        err = _err("NOT_FOUND", "User not found")
        _log_call("jira_search", "error", jira_connection_id_used=jira_connection_id, user_id_used=user_id, extra=err, started=started)
        return err
    if user.get("status") in ("disabled", "deleted"):
        err = _err("UNAUTHORIZED", "User is not allowed to perform this operation")
        _log_call("jira_search", "error", jira_connection_id_used=jira_connection_id, user_id_used=user_id, extra=err, started=started)
        return err

    conn = next((c for c in conns if isinstance(c, dict) and c.get("id") == jira_connection_id), None)
    if not conn:
        err = _err("NOT_FOUND", "Jira connection not found")
        _log_call("jira_search", "error", jira_connection_id_used=jira_connection_id, user_id_used=user_id, extra=err, started=started)
        return err
    if conn.get("user_id") != user_id:
        err = _err("UNAUTHORIZED", "Jira connection does not belong to user")
        _log_call("jira_search", "error", jira_connection_id_used=jira_connection_id, user_id_used=user_id, extra=err, started=started)
        return err

    # Expire token if past token_expires_at
    now = _now()
    token_expires_at = _parse_dt(conn.get("token_expires_at"))
    if token_expires_at and token_expires_at < now and conn.get("status") == "active":
        # active -> expired transition is allowed
        conn["status"] = "expired"
        conn["updated_at"] = _iso(now)
        _save("jira_connections.json", conns)

    # Require active connection (or refresh to become active) for search per business rules.
    # Offline: "refresh" can only "activate" if token material exists and token isn't expired too far; best-effort.
    status = conn.get("status")
    if status not in ("active", "expired"):
        err = _err("UNAUTHORIZED", "Jira connection is not authorized/active for searching", status=status)
        _log_call("jira_search", "error", jira_connection_id_used=jira_connection_id, user_id_used=user_id, extra=err, started=started)
        return err

    # If expired, attempt "refresh" only if refresh token exists (ciphertext presence is proxy).
    if status == "expired":
        if conn.get("refresh_token_ciphertext"):
            # Simulate successful refresh by moving to active and pushing expires_at forward.
            conn["status"] = "active"
            conn["token_expires_at"] = _iso(now + datetime.timedelta(hours=1))
            conn["updated_at"] = _iso(now)
            conn["last_error"] = None
            _save("jira_connections.json", conns)
        else:
            err = _err("UNAUTHORIZED", "Jira connection token expired and cannot be refreshed")
            _log_call("jira_search", "error", jira_connection_id_used=jira_connection_id, user_id_used=user_id, extra=err, started=started)
            return err

    # Cached identical search execution unless refresh=true
    cached = None
    if not refresh:
        candidates = []
        for s in searches:
            if not isinstance(s, dict):
                continue
            if s.get("jira_connection_id") == jira_connection_id and s.get("user_id") == user_id and s.get("jql") == jql and s.get("start_at") == start_at and s.get("max_results") == max_results and s.get("status") == "succeeded":
                candidates.append(s)
        def _key(s):
            return _parse_dt(s.get("executed_at")) or _parse_dt(s.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        if candidates:
            cached = sorted(candidates, key=_key, reverse=True)[0]

    # Build results
    if cached:
        # Return issues by keys/ids in preserved order, from cache if present.
        key_to_issue = {}
        for it in issues:
            if isinstance(it, dict) and it.get("jira_connection_id") == jira_connection_id and it.get("issue_key"):
                key_to_issue[it.get("issue_key")] = it

        result_issues = []
        for k in cached.get("result_issue_keys") or []:
            iss = key_to_issue.get(k)
            if iss:
                # Never return token material fields (none here, but keep consistent)
                result_issues.append(dict(iss))
        resp = {
            "search": {
                "id": cached.get("id"),
                "jql": cached.get("jql"),
                "startAt": cached.get("start_at"),
                "maxResults": cached.get("max_results"),
                "total": cached.get("total"),
                "returned": cached.get("returned_count"),
                "executed_at": cached.get("executed_at"),
                "duration_ms": cached.get("duration_ms"),
                "cached": True,
            },
            "issues": result_issues,
        }
        _log_call("jira_search", "ok", jira_connection_id_used=jira_connection_id, user_id_used=user_id, started=started)
        return resp

    # "Execute against Jira" offline: synthesize from cached issues using a minimal JQL matcher.
    # Supports a few common patterns:
    # - project = KEY
    # - project in (A,B)
    # - assignee = currentUser()  (matches conn.atlassian_account_id)
    # - assignee = "<accountId>"
    # - status = "Done" (string compare to status_name)
    # - ORDER BY <field> ASC|DESC (supports updated_at, issue_key)
    jql_norm = " ".join(jql.strip().split())

    def _parse_project_keys(j):
        m = re.search(r"\bproject\s*=\s*([A-Z][A-Z0-9_]+)\b", j, re.IGNORECASE)
        if m:
            return [m.group(1)]
        m = re.search(r"\bproject\s+in\s*\(\s*([A-Z0-9_,\s]+)\s*\)", j, re.IGNORECASE)
        if m:
            keys = []
            for part in m.group(1).split(","):
                k = part.strip()
                if re.fullmatch(r"[A-Z][A-Z0-9_]+", k):
                    keys.append(k)
            return keys or None
        return None

    def _parse_assignee(j):
        m = re.search(r"\bassignee\s*=\s*currentUser\(\s*\)\b", j, re.IGNORECASE)
        if m:
            return conn.get("atlassian_account_id")
        m = re.search(r"\bassignee\s*=\s*\"([^\"]+)\"\b", j, re.IGNORECASE)
        if m:
            return m.group(1)
        m = re.search(r"\bassignee\s*=\s*([A-Za-z0-9:\-_.]+)\b", j, re.IGNORECASE)
        if m:
            v = m.group(1)
            if v.lower() != "null":
                return v
        return None

    def _parse_status(j):
        m = re.search(r"\bstatus\s*=\s*\"([^\"]+)\"\b", j, re.IGNORECASE)
        if m:
            return m.group(1)
        m = re.search(r"\bstatus\s*=\s*([A-Za-z0-9_\- ]+)\b", j, re.IGNORECASE)
        if m:
            return m.group(1).strip()
        return None

    def _parse_order(j):
        m = re.search(r"\border\s+by\s+([A-Za-z_][A-Za-z0-9_]*)\s*(asc|desc)?\b", j, re.IGNORECASE)
        if not m:
            return None
        field = m.group(1)
        direction = (m.group(2) or "asc").lower()
        return (field, direction)

    proj_keys = _parse_project_keys(jql_norm)
    assignee = _parse_assignee(jql_norm)
    status_filter = _parse_status(jql_norm)
    order = _parse_order(jql_norm)

    # Filter eligible issues belonging to this connection
    pool = []
    for it in issues:
        if not isinstance(it, dict):
            continue
        if it.get("jira_connection_id") != jira_connection_id:
            continue
        if it.get("status") in ("deleted", "forbidden"):
            continue
        pool.append(it)

    def _matches(it):
        if proj_keys is not None:
            pk = it.get("project_key")
            if not pk or pk not in proj_keys:
                return False
        if assignee is not None:
            if it.get("assignee_account_id") != assignee:
                return False
        if status_filter is not None:
            if (it.get("status_name") or "").lower() != status_filter.lower():
                return False
        return True

    matched = [it for it in pool if _matches(it)]

    # Sort if requested
    if order:
        field, direction = order
        reverse = direction == "desc"

        def _skey(it):
            if field.lower() in ("updated", "updated_at", "updatedat"):
                dt = _parse_dt(it.get("updated_at")) or _parse_dt(it.get("last_fetched_at"))
                return dt or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            if field.lower() in ("key", "issuekey", "issue_key"):
                return it.get("issue_key") or ""
            return it.get(field) or ""
        matched.sort(key=_skey, reverse=reverse)
    else:
        matched.sort(key=lambda x: (x.get("issue_key") or ""))

    total = len(matched)
    page = matched[start_at:start_at + max_results]
    returned_count = len(page)

    # "Upsert" returned issues: refresh last_fetched_at/raw_issue_json/updated_at, and status -> active
    now2 = _now()
    issue_index_by_key = {}
    for idx, it in enumerate(issues):
        if isinstance(it, dict) and it.get("jira_connection_id") == jira_connection_id and it.get("issue_key"):
            issue_index_by_key[it.get("issue_key")] = idx

    updated_any = False
    result_issue_keys = []
    result_issue_ids = []
    for it in page:
        k = it.get("issue_key")
        if not k:
            continue
        result_issue_keys.append(k)
        if it.get("jira_issue_id"):
            result_issue_ids.append(it.get("jira_issue_id"))
        idx = issue_index_by_key.get(k)
        if idx is not None:
            existing = issues[idx]
            # legal transitions: stale->active, forbidden->active, active stays active
            if existing.get("status") in ("stale", "forbidden"):
                existing["status"] = "active"
            existing["last_fetched_at"] = _iso(now2)
            if not isinstance(existing.get("raw_issue_json"), dict):
                existing["raw_issue_json"] = {}
            existing["updated_at"] = _iso(now2)
            issues[idx] = existing
            updated_any = True

    if updated_any:
        _save("jira_issues.json", issues)

    duration_ms = int(max(1, (_now() - started).total_seconds() * 1000))

    search_row = {
        "id": _gen_id("jse"),
        "jira_connection_id": jira_connection_id,
        "user_id": user_id,
        "jql": jql,
        "start_at": start_at,
        "max_results": max_results,
        "returned_count": returned_count,
        "total": total,
        "result_issue_keys": result_issue_keys,
        "result_issue_ids": result_issue_ids,
        "executed_at": _iso(_now()),
        "duration_ms": duration_ms,
        "status": "succeeded",
        "error": None,
        "created_at": _iso(_now()),
        "updated_at": _iso(_now()),
    }
    searches.append(search_row)
    _save("jira_searches.json", searches)

    resp = {
        "search": {
            "id": search_row["id"],
            "jql": jql,
            "startAt": start_at,
            "maxResults": max_results,
            "total": total,
            "returned": returned_count,
            "executed_at": search_row["executed_at"],
            "duration_ms": duration_ms,
            "cached": False,
        },
        "issues": [dict(it) for it in page],
    }
    _log_call("jira_search", "ok", jira_connection_id_used=jira_connection_id, user_id_used=user_id, started=started)
    return resp

def list_projects(jira_connection_id, status=None, archived=None, deleted=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0441000" if __import__("os").path.isdir("./environment_mix/0441000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        return dt

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        raw = (str(time.time_ns()) + os.urandom(16).hex()).encode("utf-8")
        digest = hashlib.sha256(raw).digest()
        out = []
        for b in digest:
            out.append(alphabet[b & 31])
            if len(out) >= 22:
                break
        return f"{prefix}_{''.join(out)}"

    def _log_call(endpoint, status_s, jira_connection_id_used=None, user_id_used=None, extra=None, started=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now()
        latency_ms = None
        if isinstance(started, datetime.datetime):
            latency_ms = int(max(0, (now - started).total_seconds() * 1000))
        row = {
            "id": _gen_id("rql"),
            "endpoint": endpoint,
            "status": status_s,
            "jira_connection_id": jira_connection_id_used,
            "user_id": user_id_used,
            "timestamp": _iso(now),
            "latency_ms": latency_ms,
        }
        if isinstance(extra, dict) and extra:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_check(endpoint, jira_connection_id_used=None):
        rate_limits = _load("rate_limits.json")
        if not isinstance(rate_limits, dict):
            return None
        policy = rate_limits.get("policy") if isinstance(rate_limits.get("policy"), dict) else {}
        rules = policy.get(endpoint) if isinstance(policy.get(endpoint), dict) else policy.get("default", {})
        if not isinstance(rules, dict):
            rules = {}
        per_min = rules.get("per_minute")
        scope = rules.get("scope", "connection")
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now = _now()

        def _match(r):
            if not isinstance(r, dict):
                return False
            if r.get("endpoint") != endpoint:
                return False
            if scope == "connection" and jira_connection_id_used:
                return r.get("jira_connection_id") == jira_connection_id_used
            return True

        if isinstance(per_min, int) and per_min >= 0:
            cutoff = now - datetime.timedelta(minutes=1)
            c = 0
            for r in logs:
                if not _match(r):
                    continue
                ts = _parse_dt(r.get("timestamp"))
                if ts and ts >= cutoff:
                    c += 1
            if c >= per_min:
                return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    started = _now()

    pat_jcn = re.compile(r"^jcn_[0-9A-HJKMNP-TV-Z]{16,}$")
    if not isinstance(jira_connection_id, str) or not pat_jcn.match(jira_connection_id):
        err = _err("VALIDATION_ERROR", "Invalid jira_connection_id")
        _log_call("list_projects", "error", jira_connection_id_used=jira_connection_id, extra=err, started=started)
        return err
    if status is not None and (not isinstance(status, str) or status not in ("active", "stale", "disabled")):
        err = _err("VALIDATION_ERROR", "Invalid status filter")
        _log_call("list_projects", "error", jira_connection_id_used=jira_connection_id, extra=err, started=started)
        return err
    if archived is not None and not isinstance(archived, bool):
        err = _err("VALIDATION_ERROR", "archived must be a boolean")
        _log_call("list_projects", "error", jira_connection_id_used=jira_connection_id, extra=err, started=started)
        return err
    if deleted is not None and not isinstance(deleted, bool):
        err = _err("VALIDATION_ERROR", "deleted must be a boolean")
        _log_call("list_projects", "error", jira_connection_id_used=jira_connection_id, extra=err, started=started)
        return err
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        err = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
        _log_call("list_projects", "error", jira_connection_id_used=jira_connection_id, extra=err, started=started)
        return err
    if cursor is not None and not isinstance(cursor, str):
        err = _err("VALIDATION_ERROR", "cursor must be a string")
        _log_call("list_projects", "error", jira_connection_id_used=jira_connection_id, extra=err, started=started)
        return err

    rl = _rate_check("list_projects", jira_connection_id_used=jira_connection_id)
    if rl:
        _log_call("list_projects", "error", jira_connection_id_used=jira_connection_id, extra=rl, started=started)
        return rl

    conns = _load("jira_connections.json")
    users = _load("users.json")
    projects = _load("jira_projects.json")

    if not isinstance(conns, list) or not isinstance(users, list) or not isinstance(projects, list):
        err = _err("CONFLICT", "Datastore is in an unexpected format")
        _log_call("list_projects", "error", jira_connection_id_used=jira_connection_id, extra=err, started=started)
        return err

    conn = next((c for c in conns if isinstance(c, dict) and c.get("id") == jira_connection_id), None)
    if not conn:
        err = _err("NOT_FOUND", "Jira connection not found")
        _log_call("list_projects", "error", jira_connection_id_used=jira_connection_id, extra=err, started=started)
        return err

    user = next((u for u in users if isinstance(u, dict) and u.get("id") == conn.get("user_id")), None)
    if not user:
        err = _err("UNAUTHORIZED", "Calling context is not recognized")
        _log_call("list_projects", "error", jira_connection_id_used=jira_connection_id, extra=err, started=started)
        return err
    if user.get("status") in ("disabled", "deleted"):
        err = _err("UNAUTHORIZED", "User is not allowed to perform this operation")
        _log_call("list_projects", "error", jira_connection_id_used=jira_connection_id, user_id_used=user.get("id"), extra=err, started=started)
        return err

    # Require active connection (or refresh to active)
    now = _now()
    token_expires_at = _parse_dt(conn.get("token_expires_at"))
    if token_expires_at and token_expires_at < now and conn.get("status") == "active":
        conn["status"] = "expired"
        conn["updated_at"] = _iso(now)
        _save("jira_connections.json", conns)

    if conn.get("status") == "expired":
        if conn.get("refresh_token_ciphertext"):
            conn["status"] = "active"
            conn["token_expires_at"] = _iso(now + datetime.timedelta(hours=1))
            conn["updated_at"] = _iso(now)
            conn["last_error"] = None
            _save("jira_connections.json", conns)
        else:
            err = _err("UNAUTHORIZED", "Jira connection token expired and cannot be refreshed")
            _log_call("list_projects", "error", jira_connection_id_used=jira_connection_id, user_id_used=user.get("id"), extra=err, started=started)
            return err

    if conn.get("status") != "active":
        err = _err("UNAUTHORIZED", "Jira connection is not active", status=conn.get("status"))
        _log_call("list_projects", "error", jira_connection_id_used=jira_connection_id, user_id_used=user.get("id"), extra=err, started=started)
        return err

    # Pagination cursor: base64url("offset:<n>")
    offset = 0
    if cursor:
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            if raw.startswith("offset:"):
                offset = int(raw.split(":", 1)[1])
                if offset < 0:
                    raise ValueError()
            else:
                raise ValueError()
        except Exception:
            err = _err("VALIDATION_ERROR", "Invalid cursor")
            _log_call("list_projects", "error", jira_connection_id_used=jira_connection_id, user_id_used=user.get("id"), extra=err, started=started)
            return err

    rows = [p for p in projects if isinstance(p, dict) and p.get("jira_connection_id") == jira_connection_id]

    if status is not None:
        rows = [p for p in rows if p.get("status") == status]
    if archived is not None:
        rows = [p for p in rows if bool(p.get("archived")) == archived]
    if deleted is not None:
        rows = [p for p in rows if bool(p.get("deleted")) == deleted]

    # Stable sort by project_key then id
    rows.sort(key=lambda p: ((p.get("project_key") or ""), (p.get("id") or "")))

    total = len(rows)
    page = rows[offset:offset + limit]
    next_cursor = None
    if offset + limit < total:
        next_cursor = base64.urlsafe_b64encode(f"offset:{offset + limit}".encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "projects": [dict(p) for p in page],
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": next_cursor is not None,
            "next_cursor": next_cursor,
        },
    }
    _log_call("list_projects", "ok", jira_connection_id_used=jira_connection_id, user_id_used=user.get("id"), started=started)
    return resp

