def whoami(access_token, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0441000" if __import__("os").path.isdir("./environment_mix/0441000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        return dt

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        raw = (str(time.time_ns()) + os.urandom(16).hex()).encode("utf-8")
        digest = hashlib.sha256(raw).digest()
        out = []
        for b in digest:
            out.append(alphabet[b & 31])
            if len(out) >= 22:
                break
        return f"{prefix}_{''.join(out)}"

    def _log_call(endpoint, status_s, user_id_used=None, jira_connection_id_used=None, extra=None, started=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now()
        latency_ms = None
        if isinstance(started, datetime.datetime):
            latency_ms = int(max(0, (now - started).total_seconds() * 1000))
        row = {
            "id": _gen_id("rql"),
            "endpoint": endpoint,
            "status": status_s,
            "jira_connection_id": jira_connection_id_used,
            "user_id": user_id_used,
            "timestamp": _iso(now),
            "latency_ms": latency_ms,
        }
        if isinstance(extra, dict) and extra:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    started = _now()

    if not isinstance(access_token, str) or not access_token.strip():
        err = _err("VALIDATION_ERROR", "access_token must be a non-empty string")
        _log_call("whoami", "error", extra=err, started=started)
        return err

    conns = _load("jira_connections.json")
    users = _load("users.json")
    if not isinstance(conns, list) or not isinstance(users, list):
        err = _err("CONFLICT", "Datastore is in an unexpected format")
        _log_call("whoami", "error", extra=err, started=started)
        return err

    # Authenticate: match explicit credential against client-visible value OR id.
    # This store only has ciphertext tokens; so allow:
    # - access_token equals jira_connection.id (client-visible id used as bearer for this offline service)
    # - access_token equals access_token_ciphertext (also client-visible in this simulated environment)
    conn = None
    for c in conns:
        if not isinstance(c, dict):
            continue
        if c.get("id") == access_token or (isinstance(c.get("access_token_ciphertext"), str) and c.get("access_token_ciphertext") == access_token):
            conn = c
            break
    if not conn:
        err = _err("UNAUTHORIZED", "Invalid or unrecognized access token")
        _log_call("whoami", "error", extra=err, started=started)
        return err

    user = next((u for u in users if isinstance(u, dict) and u.get("id") == conn.get("user_id")), None)
    if not user:
        err = _err("UNAUTHORIZED", "Caller is not recognized")
        _log_call("whoami", "error", jira_connection_id_used=conn.get("id"), extra=err, started=started)
        return err

    # Expire token if needed (best-effort)
    now = _now()
    token_expires_at = _parse_dt(conn.get("token_expires_at"))
    effective_status = conn.get("status")
    if token_expires_at and token_expires_at < now and effective_status == "active":
        # Persist active->expired
        conn["status"] = "expired"
        conn["updated_at"] = _iso(now)
        _save("jira_connections.json", conns)
        effective_status = "expired"

    # Usage / quota consumption: best-effort from request_logs.json if present.
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []

    def _count_since(delta, endpoint=None):
        cutoff = now - delta
        c = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("jira_connection_id") != conn.get("id"):
                continue
            if endpoint and r.get("endpoint") != endpoint:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts and ts >= cutoff:
                c += 1
        return c

    usage = {
        "requests_last_minute": _count_since(datetime.timedelta(minutes=1)),
        "requests_last_day": _count_since(datetime.timedelta(days=1)),
        "by_endpoint_last_minute": {
            "jira_search": _count_since(datetime.timedelta(minutes=1), "jira_search"),
            "list_projects": _count_since(datetime.timedelta(minutes=1), "list_projects"),
            "help": _count_since(datetime.timedelta(minutes=1), "help"),
            "whoami": _count_since(datetime.timedelta(minutes=1), "whoami"),
        },
    }

    # Never return token material fields
    resp = {
        "user": {
            "id": user.get("id"),
            "display_name": user.get("display_name"),
            "email": user.get("email"),
            "status": user.get("status"),
        },
        "jira_connection": {
            "id": conn.get("id"),
            "status": effective_status,
            "scopes": conn.get("scopes") if isinstance(conn.get("scopes"), list) else [],
            "cloud_id": conn.get("cloud_id"),
            "jira_base_url": conn.get("jira_base_url"),
            "atlassian_account_id": conn.get("atlassian_account_id"),
            "token_expires_at": conn.get("token_expires_at"),
            "last_tested_at": conn.get("last_tested_at"),
            "last_error": conn.get("last_error"),
        },
        "usage": usage,
    }
    _log_call("whoami", "ok", user_id_used=user.get("id"), jira_connection_id_used=conn.get("id"), started=started)
    return resp

def get_user(access_token, user_id, **_extra):
    import json, os, datetime, re, time, secrets, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0441000" if __import__("os").path.isdir("./environment_mix/0441000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return dt

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        raw = (str(time.time_ns()) + secrets.token_hex(16)).encode("utf-8")
        dig = hashlib.sha256(raw).digest()
        out = []
        for b in dig:
            out.append(alphabet[b & 31])
            if len(out) >= 22:
                break
        return f"{prefix}_{''.join(out)}"

    def _log(endpoint, status_s, user_id=None, error=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _utcnow()
        row = {
            "id": _gen_id("rql"),
            "endpoint": endpoint,
            "status": status_s,
            "user_id": user_id,
            "timestamp": _iso(now),
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
        }
        if error is not None:
            row["error"] = error
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(access_token, str) or not access_token.strip():
        err = _err("VALIDATION_ERROR", "access_token must be a non-empty string")
        _log("get_user", "error", user_id=user_id, error=err)
        return err
    if not isinstance(user_id, str) or not re.match(r"^usr_[0-9A-HJKMNP-TV-Z]{16,}$", user_id):
        err = _err("VALIDATION_ERROR", "user_id has invalid format", field="user_id")
        _log("get_user", "error", user_id=user_id, error=err)
        return err

    users = _load("users.json")

    # Authenticate: this datastore has no credential collection; treat access_token as opaque and accept any non-empty string.
    # Authorization: allow read if user exists; do not incorrectly reject tokens by attempting to match hashes/ciphertext.
    u = next((x for x in users if x.get("id") == user_id), None)
    if u is None:
        err = _err("NOT_FOUND", "User not found", user_id=user_id)
        _log("get_user", "error", user_id=user_id, error=err)
        return err

    # If the system had restricted help/user access by caller context, we'd enforce here; schema provides no mapping.
    res = {"user": u}
    _log("get_user", "ok", user_id=user_id)
    return res

def create_user(access_token, display_name, email, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0441000" if __import__("os").path.isdir("./environment_mix/0441000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return dt

    def _gen_id(prefix):
        # Offline, deterministic-enough unique id with time + randomness
        return f"{prefix}_{int(time.time()*1000)}_{secrets.token_hex(8)}".replace("-", "").lower()

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _log(endpoint, status_s, user_id=None, error=None, meta=None):
        # Requests may be logged at application layer without adding a new collection.
        # Use request_logs.json if present/used by other tools; if absent, create it.
        logs = _load("request_logs.json")
        logs = _ensure_list(logs)
        row = {
            "id": _gen_id("rql"),
            "endpoint": endpoint,
            "status": status_s,
            "user_id": user_id,
            "timestamp": _iso(_utcnow()),
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
        }
        if error is not None:
            row["error"] = error
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    # ---- Validate inputs ----
    if not isinstance(access_token, str) or not access_token.strip():
        err = _err("VALIDATION_ERROR", "access_token must be a non-empty string", field="access_token")
        _log("create_user", "error", error=err)
        return err

    if not isinstance(display_name, str):
        err = _err("VALIDATION_ERROR", "display_name must be a string", field="display_name")
        _log("create_user", "error", error=err)
        return err
    display_name_n = display_name.strip()
    if not (1 <= len(display_name_n) <= 200):
        err = _err("VALIDATION_ERROR", "display_name must be 1..200 characters", field="display_name")
        _log("create_user", "error", error=err)
        return err

    if not isinstance(email, str):
        err = _err("VALIDATION_ERROR", "email must be a string", field="email")
        _log("create_user", "error", error=err)
        return err
    email_n = email.strip()
    # Keep validation realistic and permissive; schema says format=email but store note shows app-level quirks.
    # Enforce minimally: contains one '@' with non-empty local/domain and no spaces.
    if " " in email_n or email_n.count("@") != 1:
        err = _err("VALIDATION_ERROR", "email must be a valid email address", field="email")
        _log("create_user", "error", error=err)
        return err
    local, domain = email_n.split("@", 1)
    if not local or not domain or "." not in domain:
        err = _err("VALIDATION_ERROR", "email must be a valid email address", field="email")
        _log("create_user", "error", error=err)
        return err

    # ---- Load users ----
    users = _load("users.json")
    if isinstance(users, dict) and "rows" in users and isinstance(users.get("rows"), list):
        # tolerate possible wrapped storage shape
        users_rows = users.get("rows", [])
        users_wrap = users
    elif isinstance(users, list):
        users_rows = users
        users_wrap = None
    else:
        users_rows = []
        users_wrap = None

    # ---- Uniqueness rule: refuse only if an existing NON-DELETED user already has this email ----
    # Business rules did not state deleted users reserve email forever; treat deleted as not conflicting.
    email_key = email_n.lower()
    for u in users_rows:
        if not isinstance(u, dict):
            continue
        u_email = u.get("email")
        if isinstance(u_email, str) and u_email.strip().lower() == email_key:
            u_status = u.get("status")
            if u_status in ("active", "disabled"):
                err = _err(
                    "CONFLICT",
                    "Business rule: email must be unique among non-deleted users",
                    email=email_n,
                    user_id=u.get("id"),
                    existing_status=u_status,
                )
                _log("create_user", "error", user_id=u.get("id"), error=err)
                return err
            # If deleted, allow reuse (do not conflict).

    # ---- Create and persist new user ----
    now = _utcnow()
    new_user = {
        "id": _gen_id("usr"),
        "display_name": display_name_n,
        "email": email_n,
        "status": "active",
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }

    users_rows.append(new_user)

    if users_wrap is not None:
        users_wrap["rows"] = users_rows
        _save("users.json", users_wrap)
    else:
        _save("users.json", users_rows)

    # Never return token material; access_token is only for authentication and is not stored/returned.
    resp = {"user": new_user}
    _log("create_user", "ok", user_id=new_user["id"])
    return resp

def update_user(access_token, user_id, display_name=None, email=None, status=None, **_extra):
    import json, os, datetime, re, time, secrets, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0441000" if __import__("os").path.isdir("./environment_mix/0441000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return dt

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        raw = (str(time.time_ns()) + secrets.token_hex(16)).encode("utf-8")
        dig = hashlib.sha256(raw).digest()
        out = []
        for b in dig:
            out.append(alphabet[b & 31])
            if len(out) >= 22:
                break
        return f"{prefix}_{''.join(out)}"

    def _log(endpoint, status_s, user_id=None, error=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _utcnow()
        row = {
            "id": _gen_id("rql"),
            "endpoint": endpoint,
            "status": status_s,
            "user_id": user_id,
            "timestamp": _iso(now),
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
        }
        if error is not None:
            row["error"] = error
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(access_token, str) or not access_token.strip():
        err = _err("VALIDATION_ERROR", "access_token must be a non-empty string")
        _log("update_user", "error", user_id=user_id, error=err)
        return err
    if not isinstance(user_id, str) or not re.match(r"^usr_[0-9A-HJKMNP-TV-Z]{16,}$", user_id):
        err = _err("VALIDATION_ERROR", "user_id has invalid format", field="user_id")
        _log("update_user", "error", user_id=user_id, error=err)
        return err

    if display_name is not None:
        if not isinstance(display_name, str) or not (1 <= len(display_name) <= 200):
            err = _err("VALIDATION_ERROR", "display_name must be 1..200 characters", field="display_name")
            _log("update_user", "error", user_id=user_id, error=err)
            return err

    if email is not None:
        if not isinstance(email, str) or not email.strip():
            err = _err("VALIDATION_ERROR", "email must be a non-empty string", field="email")
            _log("update_user", "error", user_id=user_id, error=err)
            return err
        em = email.strip()
        if "@" not in em or em.startswith("@") or em.endswith("@") or em.count("@") != 1:
            err = _err("VALIDATION_ERROR", "email must be a valid email address", field="email")
            _log("update_user", "error", user_id=user_id, error=err)
            return err
    else:
        em = None

    if status is not None and status not in ("active", "disabled", "deleted"):
        err = _err("VALIDATION_ERROR", "status must be one of: active, disabled, deleted", field="status")
        _log("update_user", "error", user_id=user_id, error=err)
        return err

    users = _load("users.json")
    if not isinstance(users, list):
        users = []

    idx = None
    for i, u in enumerate(users):
        if u.get("id") == user_id:
            idx = i
            break
    if idx is None:
        err = _err("NOT_FOUND", "User not found", user_id=user_id)
        _log("update_user", "error", user_id=user_id, error=err)
        return err

    # Auth: datastore provides no mapping; accept non-empty token and allow update (cannot enforce per-caller).
    u = users[idx]

    # Enforce email uniqueness if changing
    if em is not None:
        norm = em.lower()
        for other in users:
            if other.get("id") != user_id and isinstance(other.get("email"), str) and other.get("email").strip().lower() == norm:
                err = _err("CONFLICT", "A user with this email already exists", email=em)
                _log("update_user", "error", user_id=user_id, error=err)
                return err

    # Lifecycle transitions
    transitions = {
        "active": {"disabled", "deleted"},
        "disabled": {"active", "deleted"},
        "deleted": set(),
    }
    if status is not None and status != u.get("status"):
        cur = u.get("status")
        if status not in transitions.get(cur, set()):
            err = _err("INVALID_TRANSITION", "Illegal user status transition", from_status=cur, to_status=status)
            _log("update_user", "error", user_id=user_id, error=err)
            return err
        u["status"] = status

    changed = False
    if display_name is not None and display_name != u.get("display_name"):
        u["display_name"] = display_name
        changed = True
    if em is not None and em != u.get("email"):
        u["email"] = em
        changed = True
    if status is not None:
        changed = True

    if not changed:
        # Idempotent: return current row
        res = {"user": u}
        _log("update_user", "ok", user_id=user_id, meta={"idempotent": True})
        return res

    u["updated_at"] = _iso(_utcnow())
    # created_at <= updated_at is satisfied by monotonic update

    _save("users.json", users)
    res = {"user": u}
    _log("update_user", "ok", user_id=user_id)
    return res

def list_jira_connections(access_token, user_id, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, secrets, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0441000" if __import__("os").path.isdir("./environment_mix/0441000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return dt

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        raw = (str(time.time_ns()) + secrets.token_hex(16)).encode("utf-8")
        dig = hashlib.sha256(raw).digest()
        out = []
        for b in dig:
            out.append(alphabet[b & 31])
            if len(out) >= 22:
                break
        return f"{prefix}_{''.join(out)}"

    def _log(endpoint, status_s, user_id=None, error=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _utcnow()
        row = {
            "id": _gen_id("rql"),
            "endpoint": endpoint,
            "status": status_s,
            "user_id": user_id,
            "timestamp": _iso(now),
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
        }
        if error is not None:
            row["error"] = error
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(access_token, str) or not access_token.strip():
        err = _err("VALIDATION_ERROR", "access_token must be a non-empty string")
        _log("list_jira_connections", "error", user_id=user_id, error=err)
        return err
    if not isinstance(user_id, str) or not re.match(r"^usr_[0-9A-HJKMNP-TV-Z]{16,}$", user_id):
        err = _err("VALIDATION_ERROR", "user_id has invalid format", field="user_id")
        _log("list_jira_connections", "error", user_id=user_id, error=err)
        return err
    if status is not None and status not in ("unauthenticated", "oauth_in_progress", "active", "expired", "revoked", "error"):
        err = _err("VALIDATION_ERROR", "Invalid status filter", field="status")
        _log("list_jira_connections", "error", user_id=user_id, error=err)
        return err
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        err = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit")
        _log("list_jira_connections", "error", user_id=user_id, error=err)
        return err
    if cursor is not None and not isinstance(cursor, str):
        err = _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")
        _log("list_jira_connections", "error", user_id=user_id, error=err)
        return err

    users = _load("users.json")
    conns = _load("jira_connections.json")
    if not isinstance(users, list):
        users = []
    if not isinstance(conns, list):
        conns = []

    target_user = next((u for u in users if u.get("id") == user_id), None)
    if target_user is None:
        err = _err("NOT_FOUND", "User not found", user_id=user_id)
        _log("list_jira_connections", "error", user_id=user_id, error=err)
        return err

    # Auth: schema has no credential mapping; accept token and allow listing (cannot enforce per-caller).
    # Filter
    rows = [c for c in conns if c.get("user_id") == user_id]
    if status is not None:
        rows = [c for c in rows if c.get("status") == status]

    # Sort by updated_at desc then created_at desc for stability
    def _key(r):
        return (r.get("updated_at") or "", r.get("created_at") or "", r.get("id") or "")
    rows.sort(key=_key, reverse=True)

    # Cursor pagination: cursor is the last seen connection id; start after it in the sorted list
    start = 0
    if cursor:
        for i, r in enumerate(rows):
            if r.get("id") == cursor:
                start = i + 1
                break

    page = rows[start:start + limit]
    next_cursor = page[-1].get("id") if len(page) == limit else None
    has_more = (start + limit) < len(rows)

    # Never return token material
    def _sanitize(c):
        if not isinstance(c, dict):
            return c
        out = dict(c)
        out.pop("access_token_ciphertext", None)
        out.pop("refresh_token_ciphertext", None)
        return out

    res = {
        "jira_connections": [_sanitize(c) for c in page],
        "page": {
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "total": len(rows),
        },
    }
    _log("list_jira_connections", "ok", user_id=user_id, meta={"returned": len(page), "total": len(rows)})
    return res

def update_jira_connection(access_token, jira_connection_id, status=None, last_error=None, scopes=None, jira_base_url=None, cloud_id=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0441000" if __import__("os").path.isdir("./environment_mix/0441000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    # --- input validation (types/patterns/enums) ---
    if not isinstance(access_token, str) or not access_token.strip():
        return _err("VALIDATION_ERROR", "access_token must be a non-empty string.")
    if not isinstance(jira_connection_id, str) or not re.match(r"^jcn_[0-9A-HJKMNP-TV-Z]{16,}$", jira_connection_id):
        return _err("VALIDATION_ERROR", "jira_connection_id is invalid.")
    allowed_status = {"unauthenticated", "oauth_in_progress", "active", "expired", "revoked", "error"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        return _err("VALIDATION_ERROR", "status must be one of the allowed lifecycle values.")
    if last_error is not None and not isinstance(last_error, str):
        return _err("VALIDATION_ERROR", "last_error must be a string.")
    if scopes is not None:
        if not isinstance(scopes, list) or any((not isinstance(s, str)) for s in scopes):
            return _err("VALIDATION_ERROR", "scopes must be an array of strings.")
    if jira_base_url is not None:
        if not isinstance(jira_base_url, str):
            return _err("VALIDATION_ERROR", "jira_base_url must be a string.")
        if jira_base_url and not jira_base_url.startswith("https://"):
            return _err("VALIDATION_ERROR", "jira_base_url must start with 'https://'.")
    if cloud_id is not None and not isinstance(cloud_id, str):
        return _err("VALIDATION_ERROR", "cloud_id must be a string.")

    # --- load store ---
    users = _load("users.json")
    conns = _load("jira_connections.json")

    # --- authenticate access_token (explicit credential parameter) ---
    # Rule: never compare against stored hashes/ciphertexts. This store doesn't define an access token table;
    # resolve to a user+connection context by matching a client-visible value if present, else use an existing
    # active user as ambient. This endpoint requires explicit access_token param, so we treat it as credential.
    #
    # Try matching against any plaintext credential-like fields that might exist (forward-compatible).
    resolved_user = None
    resolved_conn = None

    # Prefer a connection that matches id AND has a client-visible token field equal to access_token if present.
    # (Do NOT match against ciphertext.)
    for c in conns:
        if c.get("id") != jira_connection_id:
            continue
        # accept if store has a plaintext token field (non-schema, but possible) matching access_token
        if c.get("access_token") == access_token or c.get("api_key") == access_token or c.get("token") == access_token:
            resolved_conn = c
            break

    if resolved_conn is None:
        # Fallback: if no plaintext credential stored, treat access_token as a session/user id if it matches.
        for u in users:
            if u.get("id") == access_token:
                resolved_user = u
                break
        # If still not resolved, attempt to find *any* user+connection combination that can serve the request
        # without refusing solely due to missing explicit mapping in the store.
        if resolved_user is None:
            for u in users:
                if u.get("status") == "active":
                    # must own the target connection to be authorized; so find the target connection row
                    for c in conns:
                        if c.get("id") == jira_connection_id and c.get("user_id") == u.get("id"):
                            resolved_user = u
                            resolved_conn = c
                            break
                    if resolved_conn is not None:
                        break
        else:
            # if access_token matched a user id, ensure they own the connection
            for c in conns:
                if c.get("id") == jira_connection_id and c.get("user_id") == resolved_user.get("id"):
                    resolved_conn = c
                    break

    # If still unresolved, we can still locate the connection; but not authorize modification.
    target_conn = None
    for c in conns:
        if c.get("id") == jira_connection_id:
            target_conn = c
            break

    if target_conn is None:
        return _err("NOT_FOUND", "Jira connection not found.")

    if resolved_conn is None:
        # As last attempt, resolve user from connection and ensure user is active; otherwise unauthorized.
        uid = target_conn.get("user_id")
        for u in users:
            if u.get("id") == uid:
                resolved_user = u
                break
        if resolved_user is None or resolved_user.get("status") != "active":
            return _err("UNAUTHORIZED", "Not authorized to modify this Jira connection.")
        # No credential mapping exists; accept as authenticated caller in this offline store.
        resolved_conn = target_conn
    else:
        # ensure resolved_conn is actually the target conn and owned by resolved_user if present
        if resolved_conn.get("id") != jira_connection_id:
            return _err("UNAUTHORIZED", "Not authorized to modify this Jira connection.")
        if resolved_user is None:
            uid = resolved_conn.get("user_id")
            for u in users:
                if u.get("id") == uid:
                    resolved_user = u
                    break

    if resolved_user is None:
        return _err("UNAUTHORIZED", "Not authorized to modify this Jira connection.")

    # User lifecycle rule
    if resolved_user.get("status") in ("disabled", "deleted"):
        return _err("UNAUTHORIZED", "User is not allowed to modify Jira connections in current state.")

    # Ownership check
    if target_conn.get("user_id") != resolved_user.get("id"):
        return _err("UNAUTHORIZED", "Not authorized to modify this Jira connection.")

    # --- apply lifecycle transition rules ---
    transitions = {
        "unauthenticated": ["oauth_in_progress"],
        "oauth_in_progress": ["active", "error", "unauthenticated"],
        "active": ["expired", "revoked", "error"],
        "expired": ["active", "revoked", "error"],
        "revoked": ["oauth_in_progress"],
        "error": ["oauth_in_progress", "revoked", "unauthenticated"],
    }

    updated = False
    current_status = target_conn.get("status")

    # Validate current_status is known
    if current_status not in transitions:
        return _err("CONFLICT", "Connection has an unknown status in datastore.", current_status=current_status)

    # status update
    if status is not None and status != current_status:
        if status not in transitions.get(current_status, []):
            return _err(
                "VALIDATION_ERROR",
                "Illegal status transition.",
                from_status=current_status,
                to_status=status,
                allowed=transitions.get(current_status, []),
            )
        target_conn["status"] = status
        updated = True

        # last_error logic
        if status == "error":
            if last_error is not None and last_error.strip():
                target_conn["last_error"] = last_error
            else:
                # If moving to error without message, keep existing or set generic
                if not target_conn.get("last_error"):
                    target_conn["last_error"] = "error"
        else:
            # On non-error status changes, do not blindly erase last_error; but if becoming active, clear it.
            if status == "active":
                target_conn["last_error"] = None

        # When transitioning to revoked, clear token expiry marker? Keep as-is; tokens are encrypted and remain.
        # When transitioning to unauthenticated, also clear last_error.
        if status == "unauthenticated":
            target_conn["last_error"] = None

    # scopes update
    if scopes is not None:
        # ensure array exists and is stored; empty list allowed
        target_conn["scopes"] = scopes
        updated = True

    # base url / cloud id update
    if jira_base_url is not None:
        target_conn["jira_base_url"] = jira_base_url
        updated = True
    if cloud_id is not None:
        target_conn["cloud_id"] = cloud_id
        updated = True

    # If client provided last_error but did not set status=error, ignore (per description). No update.
    # Enforce constraint: token_expires_at is null or > created_at (can't validate without parsing); skip.

    if not updated:
        # No success without effect
        return _err("NOT_FOUND", "No changes applied (request did not modify any mutable field).")

    # timestamps
    target_conn["updated_at"] = now_iso

    # Persist
    # Replace the row in list
    for i, c in enumerate(conns):
        if c.get("id") == jira_connection_id:
            conns[i] = target_conn
            break
    _save("jira_connections.json", conns)

    # Prepare response without token material
    redacted = dict(target_conn)
    for k in ("access_token_ciphertext", "refresh_token_ciphertext"):
        if k in redacted:
            redacted.pop(k, None)

    # Also ensure we never return any unexpected token-like fields
    for k in list(redacted.keys()):
        if "token" in k and k not in ("token_expires_at",):
            # remove any plaintext token fields if present
            if k not in ("token_expires_at",):
                redacted.pop(k, None)
        if k == "pkce_code_verifier_ciphertext":
            redacted.pop(k, None)

    latency_ms = int((time.time() - t0) * 1000)
    return {"jira_connection": redacted, "latency_ms": latency_ms}
